    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            left, right = c, w-c-1
            if left == right and left > 0:
                a = [row[:c] for row in grid]
                b = [row[c+1:] for row in grid]
                from collections import Counter
                bg = Counter(v for row in a for v in row).most_common(1)[0][0]
                return [[3 if a[r][x] == b[r][x] else bg for x in range(left)] for r in range(h)]
